{
  "updates": [
    {
      "nodeId": "1PF-0",
      "textContent": "Each row is an income from $0 to $240,000. Dot area is the 2025–26 resident marginal rate at that income, and each bracket takes its rate colour."
    },
    {
      "nodeId": "1PM-0",
      "textContent": "FIG. 01 · 44 ROWS · 4 RATES · 4 COLOURS"
    },
    {
      "nodeId": "1R5-0",
      "textContent": "Forty-eight stands on a 13 × 12.5 module pitch. One takes the 30% colour: the bracket a $90,000 income falls in."
    },
    {
      "nodeId": "1RD-0",
      "textContent": "FIG. 05 · 6 × 8 · ONE RATE"
    },
    {
      "nodeId": "1JK-0",
      "textContent": "The amber square is one module: the thickness of the beam. On screen it is 6 px. Every space, gutter, margin and type step on this page is a whole number of modules, so layouts inherit the mark's proportions."
    },
    {
      "nodeId": "1IL-0",
      "textContent": "The schedule as a screen. Each column is an income from $0 to $240,000; dot area is the 2025–26 resident marginal rate, and each bracket takes its rate colour. The texture steps exactly where the rules step."
    }
  ]
}

