content.text:
{
  "updates": [
    {
      "nodeId": "1AT-0",
      "textContent": "MARK AND STATEMENT CONFIRMED · VOICE PROPOSED"
    },
    {
      "nodeId": "1AX-0",
      "textContent": "Tax rules\nthat compile."
    },
    {
      "nodeId": "1AY-0",
      "textContent": "TaxKit's idea in one line. Every tax rule is typed code, so a request the compiler accepts is a request the engine accepts. The report comes back with its year, rule pack and trace. The mark draws the same idea as a beam held level on one stand."
    },
    {
      "nodeId": "1BN-0",
      "textContent": "TaxKit is written as one word with a capital T and K. It is Cooper Corbett's open-source project under the MIT licence, and no other organisation's branding appears with it."
    },
    {
      "nodeId": "18Q-0",
      "textContent": "ISSUE 02 · 10 OCTOBER 2026"
    },
    {
      "nodeId": "1AH-0",
      "textContent": "The Stand mark, the lockup in Onest SemiBold, the line \"Tax rules that compile.\" and Palette D: black, white and four bracket colours. Master on page 02."
    },
    {
      "nodeId": "1AK-0",
      "textContent": "The voice, type scale, grid and screen recipes. Explorations stay on page 00."
    }
  ]
}

